// Async function to download a file
async function loadText(file) {
try {
const response = await fetch(file);
if (!response.ok) {
throw new Error("HTTP Error " + response.status);;
}
myDisplayer(await response.text();
} catch(err) {
myDisplayer(err.message);
}
}

---

